package ipl.sable.transit; import java.util.*; import java.util.function.BiConsumer; import net.minecraft.world.level.Level; import dev.ryanhcode.sable.sublevel.SubLevel; import dev.ryanhcode.sable.companion.math.BoundingBox3dc; public class IplStraddlePoseMap { public record Image(Level level,BoundingBox3dc box){} public record Mapping(BoundingBox3dc box){public BoundingBox3dc mapAabb(BoundingBox3dc b){return box;}} public static Map<SubLevel,List<Image>> images=new IdentityHashMap<>(); public static void forEachStraddleInto(SubLevel s,Level l,BiConsumer<Object,Mapping> consumer){for(var i:images.getOrDefault(s,List.of()))if(i.level==l)consumer.accept(null,new Mapping(i.box));} }